<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';Auth::requireLogin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'save';if($action==='delete'){if((int)$_POST['id']===Auth::user()['id'])throw new RuntimeException('Você não pode excluir o próprio usuário.');$db->prepare('DELETE FROM users WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Usuário excluído.');}else{$name=trim($_POST['name']);$email=mb_strtolower(trim($_POST['email']));$password=(string)$_POST['password'];if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)throw new RuntimeException('Use um e-mail válido e senha com pelo menos 8 caracteres.');$db->prepare('INSERT INTO users(name,email,password_hash,role,active) VALUES(?,?,?,?,1)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$_POST['role']]);flash('success','Usuário criado.');}}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('users.php');}$rows=$db->query('SELECT id,name,email,role,active,created_at FROM users ORDER BY name')->fetchAll();require __DIR__.'/_header.php';?>
<div class="page-title"><div><h1>Usuários</h1><p>Crie acessos internos ao painel.</p></div></div><div class="admin-grid"><form method="post" class="panel form-stack"><?=csrf_field()?><input type="hidden" name="action" value="save"><h2>Novo usuário</h2><label>Nome<input name="name" required></label><label>E-mail<input type="email" name="email" required></label><label>Senha<input type="password" name="password" minlength="8" required></label><label>Perfil<select name="role"><option value="admin">Administrador</option><option value="manager">Gestor</option><option value="editor">Editor</option><option value="viewer">Somente leitura</option></select></label><button class="btn primary">Criar usuário</button></form><div class="panel"><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?php if($r['id']!==Auth::user()['id']):?><form method="post" onsubmit="return confirm('Excluir este usuário?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link-danger">Excluir</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require __DIR__.'/_footer.php';?>
